import { useRef, useState, type ReactNode, useEffect, useLayoutEffect } from "react";
import downArrow from "../../assets/down-arrow.svg";
import Tooltip from "../Util/Tooltip";

type IconButton = {
    icon: string,
    onClick: () => void;
    visible: boolean;
    tooltip?: string;
}

type ConfigButtonTemplateProps = {
    title: string;
    tooltip?: string;
    children: ReactNode;
    onOpen?: () => void;
    onClose?: () => void;
    iconButtons?: IconButton[];
    flashRef?: { current: (() => void) | undefined };
    underlineRef?: { current: ((val: boolean) => void) | undefined };
}

export default function ConfigButtonTemplate({ title, tooltip, children, onOpen, onClose, flashRef, underlineRef, iconButtons }: ConfigButtonTemplateProps) {
    const [isOpen, setOpen] = useState(false);
    const [flash, setFlash] = useState(false);
    const [underline, setUnderline] = useState(false);
    const flashTimeoutRef = useRef<number | null>(null);
    const blockNextContextMenu = useRef(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const boxRef = useRef<HTMLDivElement>(null);
    const bodyRef = useRef<HTMLDivElement>(null);
    const mounted = useRef(false);

    // The panel animates its own height in px rather than a 0fr/1fr grid row.
    // An fr row only resolves exactly at the endpoints: mid-transition the
    // container sizes itself from the content instead of the row, so its box
    // runs taller than what gets painted and the background shows through.
    useLayoutEffect(() => {
        const box = boxRef.current;
        const body = bodyRef.current;
        if (!box || !body) return;

        if (!mounted.current) {
            mounted.current = true;
            box.style.height = isOpen ? "auto" : "0px";
            return;
        }

        if (isOpen) {
            // offsetHeight, not getBoundingClientRect: the config column sits
            // under a transform: scale, and we need layout px here.
            box.style.height = `${body.offsetHeight}px`;
            const settle = (e: TransitionEvent) => {
                // let the panel track its content once it has finished opening
                if (e.propertyName === "height" && e.target === box) box.style.height = "auto";
            };
            box.addEventListener("transitionend", settle);
            return () => box.removeEventListener("transitionend", settle);
        }

        // freeze the current height (works from "auto" or from mid-animation),
        // then force a reflow so the collapse has something to animate from
        box.style.height = `${box.offsetHeight}px`;
        void box.offsetHeight;
        box.style.height = "0px";
    }, [isOpen]);

    useEffect(() => {
        const handleContextMenu = (e: MouseEvent) => {
            if (blockNextContextMenu.current) { e.preventDefault(); blockNextContextMenu.current = false; }
        };
        document.addEventListener("contextmenu", handleContextMenu, true);
        return () => document.removeEventListener("contextmenu", handleContextMenu, true);
    }, []);

    useEffect(() => {
        if (!isOpen) return;
        const handleRightClick = (e: MouseEvent) => {
            if (e.button !== 2) return;
            if (containerRef.current?.contains(e.target as Node)) {
                e.preventDefault();
                e.stopImmediatePropagation();
                blockNextContextMenu.current = true;
                setOpen(false);
            }
        };
        document.addEventListener("mousedown", handleRightClick, true);
        return () => {
            document.removeEventListener("mousedown", handleRightClick, true);
        };
    }, [isOpen]);

    if (flashRef) {
        flashRef.current = () => {
            setFlash(true);
            if (flashTimeoutRef.current) window.clearTimeout(flashTimeoutRef.current);
            flashTimeoutRef.current = window.setTimeout(() => setFlash(false), 400);
        };
    }

    if (underlineRef) {
        underlineRef.current = setUnderline;
    }

    const handleToggle = () => {
        setOpen(prev => {
            const next = !prev;
            if (next) onOpen?.();
            else onClose?.();
            return next;
        });
    };

    return (
        <div
            ref={containerRef}
            className={`flex flex-col ${isOpen ? "config-open" : ""}`}
            onContextMenu={e => { e.preventDefault(); e.stopPropagation(); }}
            onMouseDown={e => { if (e.button === 2) { e.preventDefault(); e.stopPropagation(); } }}
        >
            <Tooltip label={tooltip} placement="right">
            <button
                onClick={handleToggle}
                className={`flex flex-row items-center justify-between
                    gap-[12px] px-2 py-2 cursor-pointer bg-medgray [.config-open+div_&]:rounded-t-sm [*:last-child:not(.config-open)>&]:rounded-b-sm
                    ${flash ? "bg-medlightgray ease-out duration-100" : ""}`}
            >
                <span className={`text-[16px] truncate min-w-0 ${underline ? "underline" : ""}`}>{title}</span>
                <div className="flex flex-row gap-2.5 items-center shrink-0">
                    {iconButtons?.map((i) => (
                        <>
                            {i.visible && 
                            <Tooltip label={i.tooltip}>
                                <button
                                    className="hover:opacity-60 active:scale-90 transition-transform cursor-pointer"
                                    onClick={(e) => {
                                        if (i.onClick) i.onClick()
                                        e.stopPropagation();
                                    }}
                                >
                                    <img
                                        src={i.icon}
                                        className="w-[13px] h-[13px]"
                                    >
                                    </img>
                                </button>
                            </Tooltip>}
                        </>
                    ))}
                    <img
                        className={`w-[12px] h-[12px] transition-transform duration-150 ${isOpen ? "rotate-180" : ""}`}
                        src={downArrow}
                    />

                </div>
            </button>
            </Tooltip>

            <div ref={boxRef} className="overflow-hidden min-h-0 transition-[height] duration-150">
                <div ref={bodyRef}>
                    <div className="relative flex flex-col gap-1 bg-medgray px-2 py-2 rounded-b-sm">
                        {children}
                    </div>
                    {/* The gap below the panel lives inside the clipped area rather than being a
                        margin, so it is revealed by the same animation and the background behind it
                        only shows once the panel is fully open. */}
                    <div className="h-2" />
                </div>
            </div>
        </div>
    );
}
